import React, { useEffect, useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import api, { systemAPI } from '../api';
import calculateLengthOfService from '../utils/calculateLengthOfService';

const RESTRICTED_REGISTRATION_ROLE_DISPLAY_NAMES = [
  'Super Admin/Mayor',
  'Admin/HR (Human Resources)',
];

export default function Register() {
  const [formData, setFormData] = useState({
    staffId: '',
    firstName: '',
    middleName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: '',
    role: '',
    position: '',
    department: '',
    phone: '',
    dateOfBirth: '',
    dateHired: '',
    placeOfBirth: '',
    tinNumber: '',
    businessPartnerNumber: '',
    philhealthNo: '',
    pagibigNo: '',
    maritalStatus: '',
    address: '',
    employmentStatus: '',
    lengthOfService: '',
    monthlyBasicSalary: '',
    peraRata: '',
    grossSalary: '',
    pendingAdministrativeCase: '',
    pendingCriminalCase: '',
    salaryGrade: '',
  });
  const [rolesAndDepartments, setRolesAndDepartments] = useState(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchRolesAndDepartments = async () => {
      try {
        const response = await systemAPI.getRolesAndDepartments();
        setRolesAndDepartments(response.data);
      } catch (err) {
        console.error('Failed to fetch roles and departments:', err);
      }
    };

    fetchRolesAndDepartments();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;

    if (name === 'role') {
      const requiresDepartment = rolesAndDepartments?.roles?.[value]?.requiresDepartment;
      setFormData((prev) => ({
        ...prev,
        [name]: value,
        department: requiresDepartment ? prev.department : '',
      }));
      return;
    }

    setFormData((prev) => ({
      ...prev,
      [name]: value,
      ...(name === 'dateHired' ? { lengthOfService: calculateLengthOfService(value) } : {}),
    }));
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    // Validation
    if (!formData.staffId || !formData.firstName || !formData.lastName || !formData.email || !formData.password || !formData.role) {
      setError('Please fill in all required fields');
      setLoading(false);
      return;
    }

    const selectedRoleData = rolesAndDepartments?.roles?.[formData.role];
    if (selectedRoleData?.requiresDepartment && !formData.department) {
      setError('Department is required for the selected role');
      setLoading(false);
      return;
    }

    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      setLoading(false);
      return;
    }

    if (formData.password.length < 6) {
      setError('Password must be at least 6 characters');
      setLoading(false);
      return;
    }

    try {
      const fullName = `${formData.firstName} ${formData.middleName} ${formData.lastName}`.trim();
      const response = await api.post('/auth/register', {
        id: formData.staffId,
        name: fullName,
        email: formData.email,
        password: formData.password,
        role: formData.role,
        position: formData.position,
        department: formData.department,
        phone: formData.phone,
        dateOfBirth: formData.dateOfBirth,
        dateHired: formData.dateHired,
        placeOfBirth: formData.placeOfBirth,
        tinNumber: formData.tinNumber,
        businessPartnerNumber: formData.businessPartnerNumber,
        philhealthNo: formData.philhealthNo,
        pagibigNo: formData.pagibigNo,
        maritalStatus: formData.maritalStatus,
        address: formData.address,
        employmentStatus: formData.employmentStatus,
        lengthOfService: formData.lengthOfService,
        monthlyBasicSalary: formData.monthlyBasicSalary,
        peraRata: formData.peraRata,
        grossSalary: formData.grossSalary,
        pendingAdministrativeCase: formData.pendingAdministrativeCase,
        pendingCriminalCase: formData.pendingCriminalCase,
        salaryGrade: formData.salaryGrade,
      });

      setSuccess('Registration submitted successfully! Please wait for admin approval to login.');
      setSubmitted(true);
      // Don't auto-redirect anymore - let user see the message
    } catch (err) {
      setError(err.response?.data?.message || 'Registration failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Show success page after submission
  if (submitted) {
    return (
      <div 
        className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden"
        style={{
          backgroundImage: `linear-gradient(rgba(138, 219, 246, 0.48), rgba(255, 255, 255, 0.2)), url('/login.jpg')`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundAttachment: 'fixed',
        }}
      >
        <div className="bg-white rounded-lg shadow-lg p-8 w-full max-w-md text-center relative" style={{ opacity: 0.85 }}>
          <div className="mb-6">
            <div className="inline-block bg-green-100 text-green-600 rounded-full p-4 mb-4">
              <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
              </svg>
            </div>
            <h1 className="text-3xl font-bold text-gray-800 mb-2">Account Created!</h1>
          </div>

          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6 text-left">
            <p className="text-blue-900 font-semibold mb-2">⏳ Pending Admin Approval</p>
            <p className="text-blue-800 text-sm mb-3">
              Your account has been successfully created and submitted for admin approval.
            </p>
            <p className="text-blue-800 text-sm mb-3">
              <strong>What happens next:</strong>
            </p>
            <ul className="text-blue-800 text-sm list-disc list-inside space-y-1">
              <li>An administrator will review your registration</li>
              <li>Once approved, you'll be able to login with your credentials</li>
              <li>You'll receive a notification when your account is approved</li>
            </ul>
          </div>

          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-6">
            <p className="text-yellow-800 text-sm">
              <strong>Note:</strong> You cannot login until your account is approved by an administrator.
            </p>
          </div>

          <div className="space-y-3">
            <button
              onClick={() => navigate('/login')}
              className="w-full bg-blue-600 text-white py-2 rounded-lg font-medium hover:bg-blue-700 transition"
            >
              Go to Login
            </button>
            <button
              onClick={() => navigate('/register')}
              className="w-full bg-gray-300 text-gray-800 py-2 rounded-lg font-medium hover:bg-gray-400 transition"
            >
              Register Another Account
            </button>
          </div>

          <p className="text-gray-600 text-xs mt-6">
            Item Number: <span className="font-semibold">{formData.staffId}</span>
          </p>
        </div>
      </div>
    );
  }

  return (
    <div 
      className="min-h-screen flex items-center justify-center p-4 py-8 relative"
      style={{
        backgroundImage: `linear-gradient(rgba(138, 219, 246, 0.48), rgba(255, 255, 255, 0.2)), url('/login.jpg')`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundAttachment: 'fixed',
      }}
    >
      <div className="bg-white rounded-lg shadow-lg p-8 w-full max-w-5xl relative" style={{ opacity: 0.95 }}>
        <div className="text-center mb-8">
          <img 
            src="/logo.PNG" 
            alt="LALA LGU Logo" 
            className="w-20 h-20 mx-auto mb-4 object-contain"
          />
          <h1 className="text-3xl font-bold text-gray-800 mb-2">Create Account</h1>
          <p className="text-1xl text-gray-400">Register as a new staff member</p>
        </div>

        {error && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg mb-4">
            {error}
          </div>
        )}

        {success && (
          <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-lg mb-4">
            {success}
          </div>
        )}

        <form onSubmit={handleRegister} className="space-y-6">
          <section className="rounded-lg border border-blue-100 bg-blue-50/40 p-5">
            <h2 className="text-lg font-semibold text-blue-900 mb-4">Personal Information</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Item Number *
            </label>
            <input
              type="text"
              name="staffId"
              value={formData.staffId}
              onChange={handleChange}
              placeholder="e.g., S001"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              First Name *
            </label>
            <input
              type="text"
              name="firstName"
              value={formData.firstName}
              onChange={handleChange}
              placeholder="John"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Middle Name
            </label>
            <input
              type="text"
              name="middleName"
              value={formData.middleName}
              onChange={handleChange}
              placeholder="(Optional)"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Last Name *
            </label>
            <input
              type="text"
              name="lastName"
              value={formData.lastName}
              onChange={handleChange}
              placeholder="Doe"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Email Address *
            </label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="you@example.com"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Phone Number
            </label>
            <input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleChange}
              placeholder="e.g., 09123456789"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Date of Birth
            </label>
            <input
              type="date"
              name="dateOfBirth"
              value={formData.dateOfBirth}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Place of Birth
            </label>
            <input
              type="text"
              name="placeOfBirth"
              value={formData.placeOfBirth}
              onChange={handleChange}
              placeholder="e.g., Manila, Philippines"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              TIN #
            </label>
            <input
              type="text"
              name="tinNumber"
              value={formData.tinNumber}
              onChange={handleChange}
              placeholder="e.g., 123-456-789"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Business Partner Number</label>
            <input
              type="text"
              name="businessPartnerNumber"
              value={formData.businessPartnerNumber}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">PhilHealth Number</label>
            <input
              type="text"
              name="philhealthNo"
              value={formData.philhealthNo}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Pag-IBIG Number</label>
            <input
              type="text"
              name="pagibigNo"
              value={formData.pagibigNo}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Marital Status</label>
            <select
              name="maritalStatus"
              value={formData.maritalStatus}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            >
              <option value="">Select marital status</option>
              <option value="Single">Single</option>
              <option value="Married">Married</option>
              <option value="Widowed">Widowed</option>
              <option value="Separated">Separated</option>
              <option value="Other">Other</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Address</label>
            <input
              type="text"
              name="address"
              value={formData.address}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

            </div>
          </section>

          <section className="rounded-lg border border-blue-100 bg-blue-50/40 p-5">
            <h2 className="text-lg font-semibold text-blue-900 mb-4">Employment Information</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Role *
                </label>
                {rolesAndDepartments ? (
                  <select
                    name="role"
                    value={formData.role}
                    onChange={handleChange}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    disabled={loading}
                    required
                  >
                    <option value="">Select Role</option>
                    {Object.entries(rolesAndDepartments.roles)
                      .filter(([, roleData]) => !RESTRICTED_REGISTRATION_ROLE_DISPLAY_NAMES.includes(roleData.displayName))
                      .map(([roleKey, roleData]) => (
                        <option key={roleKey} value={roleKey}>{roleData.displayName}</option>
                      ))}
                  </select>
                ) : (
                  <input
                    type="text"
                    disabled
                    value="Loading roles..."
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg bg-gray-100 text-gray-500"
                  />
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Position</label>
                <input
                  type="text"
                  name="position"
                  value={formData.position}
                  onChange={handleChange}
                  placeholder="e.g., Administrative Officer"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  disabled={loading}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date of Employment</label>
                <input
                  type="date"
                  name="dateHired"
                  value={formData.dateHired}
                  onChange={handleChange}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  disabled={loading}
                />
              </div>

              {rolesAndDepartments?.roles?.[formData.role]?.requiresDepartment && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Department *</label>
                  <select
                    name="department"
                    value={formData.department}
                    onChange={handleChange}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    disabled={loading}
                    required
                  >
                    <option value="">Select Department</option>
                    {rolesAndDepartments.departments.map((dept) => (
                      <option key={dept} value={dept}>{dept}</option>
                    ))}
                  </select>
                </div>
              )}

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Status of Employment</label>
            <input
              type="text"
              name="employmentStatus"
              value={formData.employmentStatus}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Length of Service</label>
            <input
              type="text"
              name="lengthOfService"
              value={formData.lengthOfService}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              readOnly
              placeholder="Calculated from Date of Employment"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Monthly Basic Salary</label>
            <input
              type="number"
              min="0"
              step="0.01"
              name="monthlyBasicSalary"
              value={formData.monthlyBasicSalary}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">PERA/RATA</label>
            <input
              type="text"
              name="peraRata"
              value={formData.peraRata}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Gross Salary</label>
            <input
              type="number"
              min="0"
              step="0.01"
              name="grossSalary"
              value={formData.grossSalary}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Pending Administrative Case</label>
            <select
              name="pendingAdministrativeCase"
              value={formData.pendingAdministrativeCase}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            >
              <option value="">Not specified</option>
              <option value="true">Yes</option>
              <option value="false">No</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Pending Criminal Case</label>
            <select
              name="pendingCriminalCase"
              value={formData.pendingCriminalCase}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            >
              <option value="">Not specified</option>
              <option value="true">Yes</option>
              <option value="false">No</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Salary Grade</label>
            <input
              type="text"
              name="salaryGrade"
              value={formData.salaryGrade}
              onChange={handleChange}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
            />
          </div>

            </div>
          </section>

          <section className="rounded-lg border border-blue-100 bg-blue-50/40 p-5">
            <h2 className="text-lg font-semibold text-blue-900 mb-4">Account Credentials</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Password *
            </label>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              placeholder="••••••••"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Confirm Password *
            </label>
            <input
              type="password"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              placeholder="••••••••"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={loading}
              required
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full md:col-span-2 bg-blue-600 text-white py-3 rounded-lg font-medium hover:bg-blue-700 transition disabled:opacity-50"
          >
            {loading ? 'Registering...' : 'Register'}
          </button>
            </div>
          </section>
        </form>

        <div className="mt-6 text-center">
          <p className="text-gray-600 text-sm">
            Already have an account?{' '}
            <Link to="/login" className="text-blue-600 hover:text-blue-700 font-medium">
              Login here
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}
