import React, { useState, useEffect } from 'react';
import { staffAPI, systemAPI } from '../api';
import calculateLengthOfService from '../utils/calculateLengthOfService';

const ALLOWED_ROLE_DISPLAY_NAMES = [
  'Super Admin/Mayor',
  'Admin/HR (Human Resources)',
  'Head of Requisitioning officer',
  'Job order officer',
  'Head Officer',
  'Staff',
];

const ALLOWED_DEPARTMENTS = [
  'Accountant',
  'Assessor',
  'LCR',
  'Treasurer',
  'General Services',
  'Engineering',
  'Planning and Development',
  'Tourism',
  'DRRM',
  'Social Welfare and Development',
  'Health Office',
  'Economic Enterprise and Development',
  'Secretary to the Sangguniang Bayan',
  'Budget',
  'Agriculture',
  'Administrator',
];

function AddStaff() {
  const [formData, setFormData] = useState({
    id: '',
    firstName: '',
    middleName: '',
    lastName: '',
    email: '',
    password: '',
    role: '',
    position: '',
    department: '',
    phone: '',
    dateOfBirth: '',
    dateHired: '',
    placeOfBirth: '',
    tinNumber: '',
    businessPartnerNumber: '',
    philhealthNo: '',
    pagibigNo: '',
    maritalStatus: '',
    address: '',
    employmentStatus: '',
    lengthOfService: '',
    monthlyBasicSalary: '',
    peraRata: '',
    grossSalary: '',
    pendingAdministrativeCase: '',
    pendingCriminalCase: '',
    salaryGrade: '',
  });
  const [rolesAndDepartments, setRolesAndDepartments] = useState(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  const filteredRoles = Object.entries(rolesAndDepartments?.roles || {})
    .filter(([, roleData]) => ALLOWED_ROLE_DISPLAY_NAMES.includes(roleData.displayName))
    .sort(([, firstRoleData], [, secondRoleData]) => firstRoleData.displayName.localeCompare(secondRoleData.displayName));

  const filteredDepartments = (rolesAndDepartments?.departments || [])
    .filter((department) => ALLOWED_DEPARTMENTS.includes(department))
    .sort((firstDepartment, secondDepartment) => firstDepartment.localeCompare(secondDepartment));

  // Fetch available roles and departments on component mount
  useEffect(() => {
    const fetchRolesAndDepartments = async () => {
      try {
        const response = await systemAPI.getRolesAndDepartments();
        setRolesAndDepartments(response.data);
      } catch (err) {
        console.error('Failed to fetch roles and departments:', err);
      }
    };
    fetchRolesAndDepartments();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    
    // Reset department if role is changed and new role doesn't require department
    if (name === 'role') {
      const requiresDept = rolesAndDepartments?.roles?.[value]?.requiresDepartment;
      
      setFormData({
        ...formData,
        [name]: value,
        department: requiresDept ? formData.department : ''
      });
    } else {
      setFormData({
        ...formData,
        [name]: value,
        ...(name === 'dateHired' ? { lengthOfService: calculateLengthOfService(value) } : {}),
      });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!formData.id || !formData.firstName || !formData.lastName || !formData.email || !formData.password || !formData.role) {
      setError('ID, First Name, Last Name, Email, Password, and Role are required');
      return;
    }

    // Check if department is required for this role
    const selectedRoleData = rolesAndDepartments?.roles[formData.role];
    if (selectedRoleData?.requiresDepartment && !formData.department) {
      setError('Department is required for this role');
      return;
    }

    try {
      setLoading(true);
      const fullName = `${formData.firstName} ${formData.middleName} ${formData.lastName}`.trim();
      await staffAPI.create({
        ...formData,
        name: fullName,
      });
      setSuccess('Staff added successfully!');
      setFormData({
        id: '',
        firstName: '',
        middleName: '',
        lastName: '',
        email: '',
        password: '',
        role: '',
        position: '',
        department: '',
        phone: '',
        dateOfBirth: '',
        dateHired: '',
        placeOfBirth: '',
        tinNumber: '',
        businessPartnerNumber: '',
        philhealthNo: '',
        pagibigNo: '',
        maritalStatus: '',
        address: '',
        employmentStatus: '',
        lengthOfService: '',
        monthlyBasicSalary: '',
        peraRata: '',
        grossSalary: '',
        pendingAdministrativeCase: '',
        pendingCriminalCase: '',
        salaryGrade: '',
      });
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to add staff');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="mt-6 max-w-md">
      <h1 className="text-3xl font-bold mb-6">Add New Staff</h1>

      {error && <div className="mb-4 p-4 bg-red-100 text-red-700 rounded">{error}</div>}
      {success && <div className="mb-4 p-4 bg-green-100 text-green-700 rounded">{success}</div>}

      <form onSubmit={handleSubmit} className="bg-white p-6 rounded shadow space-y-4">
        <div>
          <label className="block font-bold mb-2">Item Number *</label>
          <input
            type="text"
            name="id"
            value={formData.id}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
            required
          />
        </div>

        <div>
          <label className="block font-bold mb-2">First Name *</label>
          <input
            type="text"
            name="firstName"
            value={formData.firstName}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
            required
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Middle Name</label>
          <input
            type="text"
            name="middleName"
            value={formData.middleName}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Last Name *</label>
          <input
            type="text"
            name="lastName"
            value={formData.lastName}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
            required
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Email *</label>
          <input
            type="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
            required
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Password *</label>
          <input
            type="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
            required
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Role *</label>
          {rolesAndDepartments ? (
            <select
              name="role"
              value={formData.role}
              onChange={handleChange}
              className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
              required
            >
              <option value="">Select a role</option>
              {filteredRoles.map(([roleKey, roleData]) => (
                <option key={roleKey} value={roleKey}>
                  {roleData.displayName}
                </option>
              ))}
            </select>
          ) : (
            <input
              type="text"
              disabled
              placeholder="Loading roles..."
              className="w-full px-4 py-2 border rounded bg-gray-100 text-gray-500"
            />
          )}
        </div>

        <div>
          <label className="block font-bold mb-2">Position</label>
          <input
            type="text"
            name="position"
            value={formData.position}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        {rolesAndDepartments?.roles[formData.role]?.requiresDepartment && (
          <div>
            <label className="block font-bold mb-2">Department *</label>
            <select
              name="department"
              value={formData.department}
              onChange={handleChange}
              className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
              required
            >
              <option value="">Select a department</option>
              {filteredDepartments.map((dept) => (
                <option key={dept} value={dept}>
                  {dept}
                </option>
              ))}
            </select>
          </div>
        )}

        <div>
          <label className="block font-bold mb-2">Phone</label>
          <input
            type="tel"
            name="phone"
            value={formData.phone}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Date of Birth</label>
          <input
            type="date"
            name="dateOfBirth"
            value={formData.dateOfBirth}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">DOE (Date of Employment)</label>
          <input
            type="date"
            name="dateHired"
            value={formData.dateHired}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Place of Birth</label>
          <input
            type="text"
            name="placeOfBirth"
            value={formData.placeOfBirth}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">TIN #</label>
          <input
            type="text"
            name="tinNumber"
            value={formData.tinNumber}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Business Partner Number</label>
          <input
            type="text"
            name="businessPartnerNumber"
            value={formData.businessPartnerNumber}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">PhilHealth Number</label>
          <input
            type="text"
            name="philhealthNo"
            value={formData.philhealthNo}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Pag-IBIG Number</label>
          <input
            type="text"
            name="pagibigNo"
            value={formData.pagibigNo}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Marital Status</label>
          <select
            name="maritalStatus"
            value={formData.maritalStatus}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          >
            <option value="">Select marital status</option>
            <option value="Single">Single</option>
            <option value="Married">Married</option>
            <option value="Widowed">Widowed</option>
            <option value="Separated">Separated</option>
            <option value="Other">Other</option>
          </select>
        </div>

        <div>
          <label className="block font-bold mb-2">Address</label>
          <input
            type="text"
            name="address"
            value={formData.address}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Status of Employment</label>
          <input
            type="text"
            name="employmentStatus"
            value={formData.employmentStatus}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Length of Service</label>
          <input
            type="text"
            name="lengthOfService"
            value={formData.lengthOfService}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
            readOnly
            placeholder="Calculated from Date of Employment"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Monthly Basic Salary</label>
          <input
            type="number"
            min="0"
            step="0.01"
            name="monthlyBasicSalary"
            value={formData.monthlyBasicSalary}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">PERA/RATA</label>
          <input
            type="text"
            name="peraRata"
            value={formData.peraRata}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Gross Salary</label>
          <input
            type="number"
            min="0"
            step="0.01"
            name="grossSalary"
            value={formData.grossSalary}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <div>
          <label className="block font-bold mb-2">Pending Administrative Case</label>
          <select
            name="pendingAdministrativeCase"
            value={formData.pendingAdministrativeCase}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          >
            <option value="">Not specified</option>
            <option value="true">Yes</option>
            <option value="false">No</option>
          </select>
        </div>

        <div>
          <label className="block font-bold mb-2">Pending Criminal Case</label>
          <select
            name="pendingCriminalCase"
            value={formData.pendingCriminalCase}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          >
            <option value="">Not specified</option>
            <option value="true">Yes</option>
            <option value="false">No</option>
          </select>
        </div>

        <div>
          <label className="block font-bold mb-2">Salary Grade</label>
          <input
            type="text"
            name="salaryGrade"
            value={formData.salaryGrade}
            onChange={handleChange}
            className="w-full px-4 py-2 border rounded focus:outline-none focus:border-blue-500"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 disabled:bg-gray-400"
        >
          {loading ? 'Adding...' : 'Add Staff'}
        </button>
      </form>
    </div>
  );
}

export default AddStaff;
